def transform(g):
    H,W=len(g),len(g[0])
    # key sequences: maximal runs of nonzero in rows having >1 nonzero
    seqs={}
    for row in g:
        nz=[j for j,v in enumerate(row) if v]
        if len(nz)>1:
            runs=[];cur=[nz[0]]
            for j in nz[1:]:
                if j==cur[-1]+1: cur.append(j)
                else: runs.append(cur);cur=[j]
            runs.append(cur)
            for r in runs:
                s=[row[j] for j in r]
                for k,v in enumerate(s): seqs[v]=(k,s)
    out=[list(row) for row in g]
    for i,row in enumerate(g):
        nz=[(j,v) for j,v in enumerate(row) if v]
        if len(nz)==1 and nz[0][1] in seqs:
            j,v=nz[0]; k,s=seqs[v]
            for m,x in enumerate(s):
                jj=j+m-k
                if 0<=jj<W: out[i][jj]=x
    return out
